import { createRequire } from 'node:module';
const require = createRequire(`${process.env.HOME}/.local/share/omgithub-playwright/package.json`);
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
const results = [];
for (const [name, width, height] of [['desktop', 1440, 900], ['mobile360', 360, 732]]) {
  const page = await browser.newPage({ viewport: { width, height } });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://127.0.0.1:8765', { waitUntil: 'load' });
  await page.locator('#cityNameInput').fill('Uji Notifikasi');
  await page.locator('#newGameBtn').click();
  await page.waitForTimeout(2600);
  const btn = page.locator('#notificationsBtn');
  await btn.click();
  const panel = page.locator('#notificationsPanel');
  await panel.waitFor({ state: 'visible' });
  const layout = await page.evaluate(() => {
    const panel = document.querySelector('#notificationsPanel').getBoundingClientRect();
    const list = document.querySelector('#notificationsList');
    const btn = document.querySelector('#notificationsBtn');
    return {
      panel: { x: panel.x, y: panel.y, width: panel.width, height: panel.height, right: panel.right, bottom: panel.bottom },
      viewport: { width: innerWidth, height: innerHeight },
      count: list.querySelectorAll('.notification-item').length,
      clearButtonVisible: !!document.querySelector('#clearNotificationsBtn')?.getClientRects().length,
      badgeExists: !!document.querySelector('#notificationBadge,.notification-badge'),
      animationClass: btn.classList.contains('is-ringing'),
      overflowingHorizontally: panel.left < 0 || panel.right > innerWidth,
      popupElements: document.querySelectorAll('.toast,.toast-popup,[role="alert"]').length
    };
  });
  await page.screenshot({ path: `/tmp/opencode/notifications-${name}.png` });
  await page.locator('#clearNotificationsBtn').click();
  const cleared = await page.locator('#notificationsList .notifications-empty').count();
  results.push({ name, layout, cleared, errors });
  await page.close();
}
await browser.close();
console.log(JSON.stringify(results, null, 2));

