import { createRequire } from 'node:module';
const require = createRequire(`${process.env.HOME}/.local/share/omgithub-playwright/package.json`);
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 360, height: 732 } });
await page.goto('http://127.0.0.1:8765', { waitUntil: 'load' });
await page.locator('#cityNameInput').fill('Uji Animasi');
await page.locator('#newGameBtn').click();
await page.waitForTimeout(760);
const first = await page.locator('#notificationsBtn .ic').evaluate(el => ({ animations: el.getAnimations().map(a => ({ name: a.animationName, playState: a.playState, currentTime: a.currentTime })) }));
await page.waitForTimeout(1450);
const second = await page.locator('#notificationsBtn .ic').evaluate(el => ({ animations: el.getAnimations().map(a => ({ name: a.animationName, playState: a.playState, currentTime: a.currentTime })) }));
console.log(JSON.stringify({ first, second }));
await browser.close();
